class HarmonicFormula:
    def __init__(self, harmonic_signature=0.35, golden_ratio=1.618):
        self.harmonic_signature = harmonic_signature
        self.golden_ratio = golden_ratio

    def calculate_pull(self, question_value, recursive_distance):
        return self.harmonic_signature * question_value / (recursive_distance ** self.golden_ratio)

    def calculate_ratios(self, question_value, min_distance=1, max_distance=10):
        pulls = [self.calculate_pull(question_value, distance) for distance in range(min_distance, max_distance + 1)]
        ratios = []

        for i in range(1, len(pulls)):
            ratio = pulls[i] / pulls[i - 1]
            ratios.append(ratio)

        return ratios, pulls

# Create an instance of the HarmonicFormula class
formula = HarmonicFormula()

# Calculate ratios for a question with a value of 4951173814691109110
ratios, pulls = formula.calculate_ratios(4951173814691109110)

# Find when the ratio flips from greater than 1 to less than 1
flip_point = None
for i in range(1, len(ratios)):
    if ratios[i - 1] > 1 and ratios[i] < 1:
        flip_point = i
        break

